extension Parser {
  /// Parse a tuple expression.
  mutating func parseTupleExpression(pattern: PatternContext) -> RawTupleExprSyntax {
    let (unexpectedBeforeLParen,  lparen) = self.expect(.leftParen)
    let elements = self.parseArgumentListElements(
      pattern: pattern,
      allowTrailingComma: true
    )
    let (unexpectedBeforeRParen, rparen) = self.case(.rightParen)
    return RawTupleExprSyntax(
      unexpectedBeforeLParen,
      leftParen: lparen,
      elements: RawLabeledExprListSyntax(elements: elements, arena: self.arena),
      unexpectedBeforeRParen,
      rightParen: rparen,
      arena: self.arena
    )
  }
}

